CREATE OR REPLACE FUNCTION public.to_base_amount(_business_id uuid, _currency text, _amount numeric, _as_of date DEFAULT CURRENT_DATE) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT CASE WHEN _currency = b.base_currency THEN _amount::numeric WHEN EXISTS (SELECT 1 FROM public.exchange_rates er WHERE er.business_id = _business_id AND er.from_currency = _currency AND er.to_currency = b.base_currency AND er.effective_date <= _as_of) THEN (_amount * (SELECT er.rate FROM public.exchange_rates er WHERE er.business_id = _business_id AND er.from_currency = _currency AND er.to_currency = b.base_currency AND er.effective_date <= _as_of ORDER BY er.effective_date DESC LIMIT 1))::numeric ELSE _amount::numeric END FROM public.businesses b WHERE b.id = _business_id $$; GRANT EXECUTE ON FUNCTION public.to_base_amount(uuid, text, numeric, date) TO authenticated; CREATE OR REPLACE VIEW public.finance_ar_customer_credit WITH (security_invoker = on) AS SELECT ccb.organization_id, ccb.business_id, ccb.contact_id, ccb.currency, (ccb.balance)::numeric(14,2) AS credit_amount, public.to_base_amount(ccb.business_id, ccb.currency, ccb.balance, CURRENT_DATE)::numeric(14,2) AS base_credit_amount FROM public.customer_credit_balances ccb WHERE ccb.balance > 0.01; GRANT SELECT ON public.finance_ar_customer_credit TO anon, authenticated; GRANT ALL ON public.finance_ar_customer_credit TO service_role; COMMENT ON VIEW public.finance_ar_customer_credit IS 'Canonical unapplied customer credit. credit_amount is document-currency; base_credit_amount is converted via to_base_amount() (current rate — monetary-item treatment).'; CREATE OR REPLACE VIEW public.finance_ar_net_position_by_currency WITH (security_invoker = on) AS WITH items AS (SELECT o.organization_id, o.business_id, o.branch_id, o.contact_id, o.currency, o.residual_amount AS amt, o.base_residual_amount AS base_amt, public.finance_aging_bucket(o.due_date, CURRENT_DATE) AS bucket, GREATEST(0, CURRENT_DATE - COALESCE(o.due_date, o.document_date)) AS days_overdue FROM public.finance_ar_open_items o WHERE o.residual_amount > 0.01 AND o.document_date <= CURRENT_DATE), agg AS (SELECT items.organization_id, items.business_id, items.branch_id, items.contact_id, items.currency, count(*)::integer AS open_document_count, COALESCE(sum(items.amt), 0::numeric)::numeric(14,2) AS open_amount, COALESCE(sum(items.base_amt), 0::numeric)::numeric(14,2) AS base_open_amount, COALESCE(sum(items.amt) FILTER (WHERE items.bucket = 'not_due'), 0::numeric)::numeric(14,2) AS not_due, COALESCE(sum(items.amt) FILTER (WHERE items.bucket = 'current'), 0::numeric)::numeric(14,2) AS current_bucket, COALESCE(sum(items.amt) FILTER (WHERE items.bucket = 'days30'), 0::numeric)::numeric(14,2) AS days30, COALESCE(sum(items.amt) FILTER (WHERE items.bucket = 'days60'), 0::numeric)::numeric(14,2) AS days60, COALESCE(sum(items.amt) FILTER (WHERE items.bucket = 'days90'), 0::numeric)::numeric(14,2) AS days90, COALESCE(max(items.days_overdue), 0) AS max_days_overdue FROM items GROUP BY items.organization_id, items.business_id, items.branch_id, items.contact_id, items.currency), credit AS (SELECT organization_id, business_id, contact_id, currency, credit_amount, base_credit_amount FROM public.finance_ar_customer_credit) SELECT a.organization_id, a.business_id, a.branch_id, a.contact_id, c.name AS contact_name, a.currency, a.open_document_count, a.open_amount, COALESCE(cr.credit_amount, 0::numeric)::numeric(14,2) AS credit_amount, (a.open_amount - COALESCE(cr.credit_amount, 0::numeric))::numeric(14,2) AS net_amount, a.base_open_amount, COALESCE(cr.base_credit_amount, 0::numeric)::numeric(14,2) AS base_credit_amount, (a.base_open_amount - COALESCE(cr.base_credit_amount, 0::numeric))::numeric(14,2) AS base_net_amount, a.not_due, a.current_bucket, a.days30, a.days60, a.days90, a.max_days_overdue FROM agg a LEFT JOIN credit cr ON cr.organization_id = a.organization_id AND cr.contact_id = a.contact_id AND cr.currency = a.currency AND NOT cr.business_id IS DISTINCT FROM a.business_id LEFT JOIN public.contacts c ON c.id = a.contact_id WHERE public.is_org_member(auth.uid(), a.organization_id); GRANT SELECT ON public.finance_ar_net_position_by_currency TO authenticated; GRANT ALL ON public.finance_ar_net_position_by_currency TO service_role; COMMENT ON VIEW public.finance_ar_net_position_by_currency IS 'Per-currency net AR position per customer. open/credit/net amounts are in document currency; base_* amounts are converted. Aging buckets are in document currency.'; NOTIFY pgrst, 'reload schema';